1	//! [`BedrockModelBuilder`] — fluent constructor for [`crate::BedrockModel`].
2	//!
3	//! ## Credentials / AWS config laziness
4	//!
5	//! The synchronous [`BedrockModelBuilder::build`] only validates the model-id
6	//! and assembles a Bedrock SDK [`Client`]; it **does not** make any network
7	//! call and **does not** verify your AWS credentials.  Credential/auth
8	//! failures surface later, at invoke time, as a
9	//! [`paigasus_helikon_core::ModelError`].
10	//!
11	//! [`BedrockModel::from_env`] loads the SDK config from the environment (an
12	//! `async` operation because it may fetch IMDS/SSO tokens), but the same
13	//! credential-laziness rule applies: loading the config does not prove the
14	//! credentials will be accepted by Bedrock.
15	
16	use std::sync::Arc;
17	
18	use aws_config::Region;
19	use aws_sdk_bedrockruntime::Client;
20	use paigasus_helikon_core::ModelCapabilities;
21	
22	use crate::capabilities::caps_for;
23	use crate::family::ModelFamily;
24	use crate::policy::{ForcedChoicePolicy, OutputPath};
25	
26	// ── BuildError ────────────────────────────────────────────────────────────────
27	
28	/// Errors that can occur while building a [`crate::BedrockModel`].
29	///
30	/// Runtime errors (auth failures, throttling, …) are reported through
31	/// [`paigasus_helikon_core::ModelError`] at invoke time, not here.
32	#[derive(Debug, thiserror::Error)]
33	#[non_exhaustive]
34	pub enum BuildError {
35	    /// No AWS SDK client or `SdkConfig` was supplied and `from_env` was not
36	    /// used.  Call `.client(…)`, `.sdk_config(…)`, or use
37	    /// [`crate::BedrockModel::from_env`].
38	    #[error("no AWS client or SdkConfig provided")]
39	    MissingClient,
40	
41	    /// The model identifier was empty.  Pass a non-empty Bedrock model id such
42	    /// as `"anthropic.claude-3-5-sonnet-20241022-v2:0"`.
43	    #[error("model id is empty")]
44	    EmptyModelId,
45	}
46	
47	// ── Config ────────────────────────────────────────────────────────────────────
48	
49	/// Resolved builder configuration held by [`crate::BedrockModel`].
50	///
51	/// Cheaply clonable via `Arc` — the `BedrockModel` holds `Arc<Config>` so
52	/// that clone + move into the `'static` stream is zero-copy.
53	#[derive(Debug, Clone)]
54	pub(crate) struct Config {
55	    /// Initialized Bedrock SDK client (region already baked in).
56	    pub(crate) client: Client,
57	    /// Bedrock model identifier (e.g. `anthropic.claude-3-5-sonnet-20241022-v2:0`).
58	    pub(crate) model_id: String,
59	    /// Detected model family used for capability routing.
60	    pub(crate) family: ModelFamily,
61	    /// Resolved capability flags for this model instance.
62	    pub(crate) capabilities: ModelCapabilities,
63	    /// Optional default for `max_tokens` when the caller does not set it.
64	    ///
65	    /// When `None` (the default), `inferenceConfig.maxTokens` is omitted from
66	    /// the Bedrock request so that each model applies its own correct limit.
67	    /// Set via [`BedrockModelBuilder::max_output_tokens_default`].
68	    pub(crate) max_output_default: Option<u32>,
69	}
70	
71	/// Make an offline [`Config`] for unit tests. The client makes no AWS call.
72	///
73	/// This function starts its own Tokio runtime, so do not call it from inside
74	/// a runtime.
75	#[cfg(test)]
76	pub(crate) fn offline_config(model_id: &str) -> Config {
77	    let family = ModelFamily::from_model_id(model_id);
78	    let capabilities = caps_for(family);
79	    let rt = tokio::runtime::Builder::new_current_thread()
80	        .enable_all()
81	        .build()
82	        .expect("tokio rt");
83	    let client = rt.block_on(async {
84	        let sdk_cfg = aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17())
85	            .region(aws_config::Region::new("us-east-1"))
86	            .test_credentials()
87	            .load()
88	            .await;
89	        Client::new(&sdk_cfg)
90	    });
91	    Config {
92	        client,
93	        model_id: model_id.to_owned(),
94	        family,
95	        capabilities,
96	        max_output_default: None,
97	    }
98	}
99	
100	// ── BedrockModelBuilder ───────────────────────────────────────────────────────
101	
102	/// Fluent builder for [`crate::BedrockModel`].
103	///
104	/// Start with [`crate::BedrockModel::converse`].
105	///
106	/// ## Credential laziness
107	///
108	/// `build()` is **synchronous** and **does not** contact any AWS endpoint.
109	/// Credential resolution happens inside the SDK client at the first
110	/// invoke call.
111	pub struct BedrockModelBuilder {
112	    model_id: String,
113	    /// Caller-supplied, fully-initialized client (highest precedence).
114	    client: Option<Client>,
115	    /// Caller-supplied `SdkConfig` (used to construct a client when no direct
116	    /// client is injected).
117	    sdk_config: Option<aws_config::SdkConfig>,
118	    /// Optional region override; ignored if a client was injected directly.
119	    region: Option<Region>,
120	    /// Optional capabilities override (wins over the `caps_for` lookup).
121	    capabilities_override: Option<ModelCapabilities>,
122	    /// Optional `max_output_tokens` override.
123	    max_output_override: Option<u32>,
124	}
125	
126	impl BedrockModelBuilder {
127	    pub(crate) fn new(model_id: impl Into<String>) -> Self {
128	        Self {
129	            model_id: model_id.into(),
130	            client: None,
131	            sdk_config: None,
132	            region: None,
133	            capabilities_override: None,
134	            max_output_override: None,
135	        }
136	    }
137	
138	    /// Inject a pre-constructed Bedrock SDK client.
139	    ///
140	    /// This takes highest precedence.  When a client is injected any
141	    /// `.region(…)` call is **ignored** (the client already has a region baked
142	    /// in) and `.sdk_config(…)` is not used to construct the client either.
143	    pub fn client(mut self, c: Client) -> Self {
144	        self.client = Some(c);
145	        self
146	    }
147	
148	    /// Build the SDK client from a caller-provided [`aws_config::SdkConfig`].
149	    ///
150	    /// Ignored if a direct client was already injected via `.client(…)`.
151	    pub fn sdk_config(mut self, c: &aws_config::SdkConfig) -> Self {
152	        self.sdk_config = Some(c.clone());
153	        self
154	    }
155	
156	    /// Override the AWS region.
157	    ///
158	    /// **Note:** this setting is **ignored** when a client is injected via
159	    /// `.client(…)` because the client already has its region baked in.  The
160	    /// region is only applied when building a client from `.sdk_config(…)` or
161	    /// when using [`crate::BedrockModel::from_env`].
162	    pub fn region(mut self, r: impl Into<Region>) -> Self {
163	        self.region = Some(r.into());
164	        self
165	    }
166	
167	    /// Override the capability flags for this model instance.
168	    ///
169	    /// Wins over the built-in `caps_for` lookup table.
170	    pub fn capabilities(mut self, c: ModelCapabilities) -> Self {
171	        self.capabilities_override = Some(c);
172	        self
173	    }
174	
175	    /// Override the default `max_output_tokens` passed to Bedrock when the
176	    /// caller does not set `ModelSettings::max_output_tokens`.
177	    pub fn max_output_tokens_default(mut self, n: u32) -> Self {
178	        self.max_output_override = Some(n);
179	        self
180	    }
181	
182	    /// Resolve all settings and construct the [`crate::BedrockModel`].
183	    ///
184	    /// This is **synchronous** — no network calls are made.
185	    ///
186	    /// # Errors
187	    ///
188	    /// - [`BuildError::EmptyModelId`] — model id is an empty string.
189	    /// - [`BuildError::MissingClient`] — neither `.client(…)` nor
190	    ///   `.sdk_config(…)` was called (use [`crate::BedrockModel::from_env`] for
191	    ///   automatic env-based client construction).
192	    pub fn build(self) -> Result<crate::BedrockModel, BuildError> {
193	        // 1. Validate model id.
194	        if self.model_id.is_empty() {
195	            return Err(BuildError::EmptyModelId);
196	        }
197	
198	        // 2. Resolve client.
199	        let client = if let Some(c) = self.client {
200	            // Injected client wins; region override is ignored.
201	            if self.region.is_some() {
202	                tracing::debug!(
203	                    target: "paigasus::bedrock::builder",
204	                    "region() was set but a Client was injected — region override ignored; \
205	                     the injected client's region takes precedence",
206	                );
207	            }
208	            c
209	        } else if let Some(ref sdk_cfg) = self.sdk_config {
210	            if let Some(region) = self.region {
211	                // Region override: build a per-client config that layers the
212	                // override on top of the caller's SdkConfig, then construct
213	                // the client from that config.
214	                let client_cfg = aws_sdk_bedrockruntime::config::Builder::from(sdk_cfg)
215	                    .region(region)
216	                    .build();
217	                aws_sdk_bedrockruntime::Client::from_conf(client_cfg)
218	            } else {
219	                Client::new(sdk_cfg)
220	            }
221	        } else {
222	            return Err(BuildError::MissingClient);
223	        };
224	
225	        // 3. Detect family and resolve capabilities.
226	        let family = ModelFamily::from_model_id(&self.model_id);
227	        if family == ModelFamily::Unknown {
228	            tracing::debug!(
229	                target: "paigasus::bedrock::builder",
230	                model_id = %self.model_id,
231	                "model family not detected from the model id; structured-output synthesis and forced tool choice are off",
232	            );
233	        }
234	        let default_caps = caps_for(family);
235	        let capabilities = self.capabilities_override.unwrap_or(default_caps);
236	        let max_output_default = self.max_output_override;
237	
238	        let policy = ForcedChoicePolicy::new(&self.model_id, family);
239	        if policy.path() == OutputPath::Native {
240	            tracing::debug!(
241	                target: "paigasus::bedrock::builder",
242	                model_id = %self.model_id,
243	                "the static rule selects native structured output for this model",
244	            );
245	        }
246	
247	        Ok(crate::BedrockModel {
248	            config: Arc::new(Config {
249	                client,
250	                model_id: self.model_id,
251	                family,
252	                capabilities,
253	                max_output_default,
254	            }),
255	            policy: Arc::new(policy),
256	        })
257	    }
258	}
259	
260	// ── BedrockModel constructors (here because they construct a builder) ─────────
261	
262	impl crate::BedrockModel {
263	    /// Start building a Bedrock model for the given model id.
264	    ///
265	    /// ```ignore
266	    /// use paigasus_helikon_providers_bedrock::BedrockModel;
267	    /// # async fn f() -> Result<(), Box<dyn std::error::Error>> {
268	    /// let model = BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
269	    ///     .sdk_config(&aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17())
270	    ///         .load().await)
271	    ///     .build()?;
272	    /// # Ok(()) }
273	    /// ```
274	    pub fn converse(model_id: impl Into<String>) -> BedrockModelBuilder {
275	        BedrockModelBuilder::new(model_id)
276	    }
277	
278	    /// Construct a [`crate::BedrockModel`] by loading AWS configuration from
279	    /// the environment (credential files, environment variables, IMDS, SSO…).
280	    ///
281	    /// ## Credential laziness
282	    ///
283	    /// The AWS credential chain is **lazy** — loading the config does not prove
284	    /// that your credentials will be accepted by Bedrock.  Auth/permission
285	    /// failures surface at invoke time as a
286	    /// [`paigasus_helikon_core::ModelError`].
287	    ///
288	    /// ## BehaviorVersion
289	    ///
290	    /// Uses the pinned `BehaviorVersion::v2026_11_17()` so that a Dependabot
291	    /// `aws-config` bump cannot silently shift SDK behavior. This version
292	    /// applies the AWS SDK retry behavior from the Retry Behavior 2.1 spec.
293	    /// It also applies a default read timeout to AWS SDK clients.
294	    ///
295	    /// ## Region
296	    ///
297	    /// Pass `None` to use the region from the environment
298	    /// (`AWS_DEFAULT_REGION`, `~/.aws/config`, …).  Pass `Some(region)` to
299	    /// override it.
300	    pub async fn from_env(model_id: impl Into<String>) -> Result<Self, BuildError> {
301	        Self::from_env_with_region(model_id, None::<Region>).await
302	    }
303	
304	    /// Like [`from_env`][Self::from_env] but with an explicit region override.
305	    pub async fn from_env_with_region(
306	        model_id: impl Into<String>,
307	        region: Option<impl Into<Region>>,
308	    ) -> Result<Self, BuildError> {
309	        let mut loader = aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17());
310	        if let Some(r) = region {
311	            loader = loader.region(r.into());
312	        }
313	        let sdk_cfg = loader.load().await;
314	        BedrockModelBuilder::new(model_id)
315	            .sdk_config(&sdk_cfg)
316	            .build()
317	    }
318	}
319	
320	// ── Unit tests ────────────────────────────────────────────────────────────────
321	
322	#[cfg(test)]
323	mod tests {
324	    use super::*;
325	    use aws_config::BehaviorVersion;
326	    use paigasus_helikon_core::Model;
327	
328	    /// Build an offline [`Client`] suitable for unit tests (no real AWS calls).
329	    fn offline_client() -> Client {
330	        // Use aws_config::ConfigLoader::test_credentials() to inject static
331	        // dummy credentials that satisfy the SDK's builder validation without
332	        // hitting any AWS endpoint.
333	        let rt = tokio::runtime::Builder::new_current_thread()
334	            .enable_all()
335	            .build()
336	            .expect("tokio runtime");
337	        rt.block_on(async {
338	            let sdk_cfg = aws_config::defaults(BehaviorVersion::v2026_11_17())
339	                .region(Region::new("us-east-1"))
340	                .test_credentials()
341	                .load()
342	                .await;
343	            Client::new(&sdk_cfg)
344	        })
345	    }
346	
347	    #[test]
348	    fn empty_model_id_returns_err_empty_model_id() {
349	        let result = crate::BedrockModel::converse("")
350	            .client(offline_client())
351	            .build();
352	        assert!(
353	            matches!(result, Err(BuildError::EmptyModelId)),
354	            "expected EmptyModelId, got {result:?}",
355	        );
356	    }
357	
358	    #[test]
359	    fn no_client_or_config_returns_err_missing_client() {
360	        let result =
361	            crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0").build();
362	        assert!(
363	            matches!(result, Err(BuildError::MissingClient)),
364	            "expected MissingClient, got {result:?}",
365	        );
366	    }
367	
368	    #[test]
369	    fn injecting_client_succeeds() {
370	        let model = crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
371	            .client(offline_client())
372	            .build()
373	            .expect("should build with injected client");
374	        assert_eq!(model.model(), "anthropic.claude-3-5-sonnet-20241022-v2:0");
375	    }
376	
377	    #[test]
378	    fn sdk_config_path_succeeds() {
379	        let rt = tokio::runtime::Builder::new_current_thread()
380	            .enable_all()
381	            .build()
382	            .expect("tokio runtime");
383	        rt.block_on(async {
384	            let sdk_cfg = aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17())
385	                .region(Region::new("eu-west-1"))
386	                .test_credentials()
387	                .load()
388	                .await;
389	            let model = crate::BedrockModel::converse("amazon.nova-pro-v1:0")
390	                .sdk_config(&sdk_cfg)
391	                .build()
392	                .expect("should build from sdk_config");
393	            assert_eq!(model.model(), "amazon.nova-pro-v1:0");
394	        });
395	    }
396	
397	    #[test]
398	    fn capabilities_come_from_caps_for_by_default() {
399	        let model = crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
400	            .client(offline_client())
401	            .build()
402	            .expect("build");
403	        let caps = model.capabilities();
404	        assert!(caps.streaming, "anthropic should report streaming");
405	        assert!(caps.tools, "anthropic should report tools");
406	        assert!(
407	            caps.structured_output,
408	            "anthropic should report structured_output"
409	        );
410	    }
411	
412	    #[test]
413	    fn capabilities_override_wins_over_lookup() {
414	        let custom = ModelCapabilities::empty();
415	        let model = crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
416	            .client(offline_client())
417	            .capabilities(custom)
418	            .build()
419	            .expect("build");
420	        let caps = model.capabilities();
421	        assert!(!caps.tools, "override should clear tools");
422	        assert!(
423	            !caps.structured_output,
424	            "override should clear structured_output"
425	        );
426	    }
427	
428	    #[test]
429	    fn max_output_override_is_stored() {
430	        let model = crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
431	            .client(offline_client())
432	            .max_output_tokens_default(1234)
433	            .build()
434	            .expect("build");
435	        assert_eq!(model.config.max_output_default, Some(1234));
436	    }
437	
438	    #[test]
439	    fn max_output_default_is_none_when_not_set() {
440	        let model = crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
441	            .client(offline_client())
442	            .build()
443	            .expect("build");
444	        assert_eq!(model.config.max_output_default, None);
445	    }
446	
447	    #[test]
448	    fn region_ignored_when_client_injected() {
449	        // Should succeed without warning-as-error: the tracing::debug! inside
450	        // build() does NOT panic. We just verify build succeeds.
451	        let model = crate::BedrockModel::converse("anthropic.claude-3-5-sonnet-20241022-v2:0")
452	            .client(offline_client())
453	            .region(Region::new("ap-southeast-1"))
454	            .build()
455	            .expect("build should succeed even when region is set with injected client");
456	        assert_eq!(model.model(), "anthropic.claude-3-5-sonnet-20241022-v2:0");
457	    }
458	
459	    /// Passing `.sdk_config()` + `.region()` should succeed and cover the
460	    /// region-override code path (we cannot inspect the baked-in region on a
461	    /// `Client` without a live endpoint, but we verify `build()` is `Ok`).
462	    #[test]
463	    fn sdk_config_with_region_override_succeeds() {
464	        let rt = tokio::runtime::Builder::new_current_thread()
465	            .enable_all()
466	            .build()
467	            .expect("tokio runtime");
468	        rt.block_on(async {
469	            let sdk_cfg = aws_config::defaults(aws_config::BehaviorVersion::v2026_11_17())
470	                .region(Region::new("eu-west-1"))
471	                .test_credentials()
472	                .load()
473	                .await;
474	            // Override to a different region via .region() on the sdk_config path.
475	            let model = crate::BedrockModel::converse("amazon.nova-pro-v1:0")
476	                .sdk_config(&sdk_cfg)
477	                .region(Region::new("ap-southeast-1"))
478	                .build()
479	                .expect("should build with region override on sdk_config path");
480	            assert_eq!(model.model(), "amazon.nova-pro-v1:0");
481	        });
482	    }
483	
484	    #[test]
485	    fn llama_family_has_no_structured_output() {
486	        let model = crate::BedrockModel::converse("meta.llama3-1-70b-instruct-v1:0")
487	            .client(offline_client())
488	            .build()
489	            .expect("build");
490	        assert!(!model.capabilities().structured_output);
491	    }
492	
493	    #[test]
494	    fn global_claude_profile_has_structured_output() {
495	        let model = crate::BedrockModel::converse("global.anthropic.claude-sonnet-5-5")
496	            .client(offline_client())
497	            .build()
498	            .expect("build");
499	        assert!(model.capabilities().structured_output);
500	        assert!(model.capabilities().parallel_tool_calls);
501	    }
502	}
