        req.tools = vec![ToolDef::new("ping", "Ping", json!({"type": "object"}))];
        req.model_settings.tool_choice = Some(ToolChoice::Required);
        let w = wire(&model, &req);
        assert_eq!(w["toolConfig"]["toolChoice"], json!({"any": {}}));
    }

